{
    "$schema": "http://json-schema.org/draft-07/schema#",
    "additionalProperties": false,
    "properties": {
        "acmeConfig": {
            "additionalProperties": false,
            "description": "Options for Automatic Certificate Management Environment client. \nRequires `enableHttps` to be set to `acme`. \nSee https://www.npmjs.com/package/greenlock-express \nSee https://tools.ietf.org/html/rfc8555 \nSee https://github.com/ietf-wg-acme/acme",
            "properties": {
                "agreeTos": {
                    "description": "Accept Let's Encrypt(TM) v2 Agreement. You must accept the ToS as the host which handles the certs. \nSee the subscriber agreement at https://letsencrypt.org/repository/",
                    "type": "boolean"
                },
                "approveDomains": {
                    "description": "Array of allowed domains such as `[ \"example.com\", \"www.example.com\" ]`",
                    "items": {
                        "type": "string"
                    },
                    "type": "array"
                },
                "communityMember": {
                    "default": false,
                    "description": "Join the Greenlock community to get notified of important updates.",
                    "type": "boolean"
                },
                "configDir": {
                    "default": "~/.config/acme/",
                    "description": "Writable directory where certs will be saved.",
                    "type": "string"
                },
                "debug": {
                    "default": false,
                    "type": "boolean"
                },
                "email": {
                    "description": "The email address of the ACME user / hosting provider.",
                    "type": "string"
                },
                "securityUpdates": {
                    "default": true,
                    "description": "Important and mandatory notices from Greenlock, related to security or breaking API changes.",
                    "type": "boolean"
                },
                "server": {
                    "default": "https://acme-v02.api.letsencrypt.org/directory",
                    "type": "string"
                },
                "servername": {
                    "description": "The default servername to use when the client doesn't specify.\nExample: \"example.com\"",
                    "type": "string"
                },
                "telemetry": {
                    "default": false,
                    "description": "Contribute telemetry data to the project.",
                    "type": "boolean"
                },
                "version": {
                    "default": "v02",
                    "description": "The ACME version to use. `v02`/`draft-12` is for Let's Encrypt v2 otherwise known as ACME draft 12.",
                    "type": "string"
                }
            },
            "required": [
                "agreeTos",
                "email",
                "securityUpdates"
            ],
            "type": "object"
        },
        "argsTransport": {
            "additionalProperties": false,
            "properties": {
                "colorize": {
                    "default": true,
                    "type": "boolean"
                },
                "handleExceptions": {
                    "default": true,
                    "type": "boolean"
                },
                "json": {
                    "default": false,
                    "type": "boolean"
                },
                "level": {
                    "default": "warn",
                    "enum": [
                        "debug",
                        "error",
                        "info",
                        "verbose",
                        "warn"
                    ],
                    "type": "string"
                },
                "timestamp": {
                    "default": true,
                    "type": "boolean"
                }
            },
            "type": "object"
        },
        "authTimestampCacheSize": {
            "default": 50000,
            "type": "integer"
        },
        "awsCredentials": {
            "additionalProperties": false,
            "description": "Required if `driver` is `aws`",
            "properties": {
                "accessKeyId": {
                    "type": "string"
                },
                "endpoint": {
                    "type": "string"
                },
                "secretAccessKey": {
                    "type": "string"
                },
                "sessionToken": {
                    "type": "string"
                }
            },
            "type": "object"
        },
        "azCredentials": {
            "additionalProperties": false,
            "description": "Required if `driver` is `azure`",
            "properties": {
                "accountKey": {
                    "type": "string"
                },
                "accountName": {
                    "type": "string"
                }
            },
            "type": "object"
        },
        "bucket": {
            "default": "hub",
            "type": "string"
        },
        "cacheControl": {
            "default": "no-cache",
            "type": "string"
        },
        "diskSettings": {
            "additionalProperties": false,
            "description": "Required if `driver` is `disk`",
            "properties": {
                "storageRootDirectory": {
                    "type": "string"
                }
            },
            "type": "object"
        },
        "driver": {
            "enum": [
                "aws",
                "azure",
                "disk",
                "google-cloud"
            ],
            "type": "string"
        },
        "enableHttps": {
            "description": "Disabled by default. \nIf set to `cert_files` then `tlsCertConfig` must be set. \nIf set to `acme` then `acmeConfig` must be set.",
            "enum": [
                "acme",
                "cert_files"
            ],
            "type": "string"
        },
        "gcCredentials": {
            "additionalProperties": false,
            "description": "Required if `driver` is `google-cloud`",
            "properties": {
                "credentials": {
                    "additionalProperties": false,
                    "properties": {
                        "client_email": {
                            "type": "string"
                        },
                        "private_key": {
                            "type": "string"
                        }
                    },
                    "type": "object"
                },
                "email": {
                    "type": "string"
                },
                "keyFilename": {
                    "type": "string"
                },
                "projectId": {
                    "type": "string"
                }
            },
            "type": "object"
        },
        "httpsPort": {
            "default": 443,
            "description": "Requires `enableHttps` to be set.",
            "maximum": 65535,
            "minimum": 0,
            "type": "integer"
        },
        "maxFileUploadSize": {
            "default": 20,
            "description": "The maximum allowed POST body size in megabytes. \nThe content-size header is checked, and the POST body stream \nis monitoring while streaming from the client. \n[Recommended] Minimum 100KB (or approximately 0.1MB)",
            "minimum": 0.1,
            "type": "number"
        },
        "pageSize": {
            "default": 100,
            "maximum": 4096,
            "minimum": 1,
            "type": "integer"
        },
        "port": {
            "default": 3000,
            "maximum": 65535,
            "minimum": 0,
            "type": "integer"
        },
        "proofsConfig": {
            "additionalProperties": false,
            "properties": {
                "proofsRequired": {
                    "default": 0,
                    "type": "integer"
                }
            },
            "type": "object"
        },
        "readURL": {
            "type": "string"
        },
        "requireCorrectHubUrl": {
            "default": false,
            "type": "boolean"
        },
        "serverName": {
            "default": "gaia-0",
            "description": "Domain name used for auth/signing challenges. \nIf `requireCorrectHubUrl` is true then this must match the hub url in an auth payload.",
            "type": "string"
        },
        "tlsCertConfig": {
            "anyOf": [
                {
                    "additionalProperties": false,
                    "properties": {
                        "certFile": {
                            "description": "Either the path to the PEM formatted certification chain file, or the string content of the file. \nThe file usually has the extension `.cert`, `.cer`, `.crt`, or `.pem`. \nIf the content string is specified, it should include the escaped EOL characters, e.g. \n`\"-----BEGIN CERTIFICATE-----\\n{lines of base64 data}\\n-----END CERTIFICATE-----\"`.",
                            "type": "string"
                        },
                        "keyFile": {
                            "description": "Either the path to the PEM formatted private key file, or the string content of the file. \nThe file usually has the extension `.key` or `.pem`. \nIf the content string is specified, it should include the escaped EOL characters, e.g. \n`\"-----BEGIN RSA PRIVATE KEY-----\\n{lines of base64 data}\\n-----END RSA PRIVATE KEY-----\"`.",
                            "type": "string"
                        },
                        "keyPassphrase": {
                            "description": "The string passphrase for the key file. If provided, the passphrase is used to decrypt the file. \nIf not provided, the key is assumed to be unencrypted.",
                            "type": "string"
                        }
                    },
                    "required": [
                        "certFile",
                        "keyFile"
                    ],
                    "type": "object"
                },
                {
                    "additionalProperties": false,
                    "properties": {
                        "pfxFile": {
                            "description": "Either the path to the PFX or PKCS12 encoded private key and certificate chain file, \nor the base64 encoded content of the file. \nThe file usually has the extension `.pfx` or `.p12`.",
                            "type": "string"
                        },
                        "pfxPassphrase": {
                            "description": "The string passphrase for the key file. If provided, the passphrase is used to decrypt the file. \nIf not provided, the key is assumed to be unencrypted.",
                            "type": "string"
                        }
                    },
                    "required": [
                        "pfxFile"
                    ],
                    "type": "object"
                }
            ],
            "description": "Options for configuring the Node.js `https` server. \nRequires `enableHttps` to be set to `tlsCertConfig`. \nSee https://nodejs.org/docs/latest-v10.x/api/https.html#https_https_createserver_options_requestlistener \nSee https://nodejs.org/docs/latest-v10.x/api/tls.html#tls_tls_createsecurecontext_options"
        },
        "validHubUrls": {
            "description": "If `requireCorrectHubUrl` is true then the hub specified in an auth payload can also be\ncontained within in array.",
            "items": {
                "type": "string"
            },
            "type": "array"
        },
        "whitelist": {
            "description": "List of ID addresses allowed to use this hub. Specifying this makes the hub private \nand only accessible to the specified addresses. Leaving this unspecified makes the hub \npublicly usable by any ID.",
            "items": {
                "type": "string"
            },
            "type": "array"
        }
    },
    "required": [
        "driver",
        "port"
    ],
    "type": "object"
}

{
    "$schema": "http://json-schema.org/draft-04/schema#",
    "additionalProperties": false,
    "id": "https://github.com/ml-learning/digital-certificates-schema/certificate-schema-v1.json",
    "properties": {
        "assertion": {
            "additionalProperties": false,
            "properties": {
                "evidence": {
                    "description": "Text, uri, etc. that shows evidence of the recipient's learning that the certificate represents. Can be left as an empty string if not used.",
                    "type": "string"
                },
                "id": {
                    "_format": "uri",
                    "description": "URI that links to the certificate on the viewer. Default is https://[domain]/[uid]",
                    "type": "string"
                },
                "image:signature": {
                    "description": "A base-64 encoded png image of the issuer's signature.",
                    "pattern": "data:image/png;base64,",
                    "type": "string"
                },
                "issuedOn": {
                    "_format": "date-time",
                    "description": "Date the the certificate JSON was created.",
                    "type": "string"
                },
                "uid": {
                    "description": "Unique identifier. By default it is created using the string of a BSON ObjectId(), yielding an identifier 24 characters long.",
                    "type": "string"
                }
            },
            "required": [
                "evidence",
                "uid",
                "issuedOn",
                "id",
                "image:signature"
            ],
            "type": "object"
        },
        "certificate": {
            "additionalProperties": false,
            "properties": {
                "description": {
                    "description": "Description of what the certificate represents. Usually one - three sentences long.",
                    "type": "string"
                },
                "id": {
                    "_format": "uri",
                    "description": "URI link to a JSON that describes the type of certificate. Default format is https://[domain]/criteria/[year]/[month]/[certificate_title].json.",
                    "type": "string"
                },
                "image": {
                    "description": "A base-64 encoded png image of the certificate's image.",
                    "pattern": "data:image/png;base64,",
                    "type": "string"
                },
                "issuer": {
                    "additionalProperties": false,
                    "description": "Details about the issuer of the certificate.",
                    "properties": {
                        "email": {
                            "_format": "email",
                            "description": "Email address of the issuer.",
                            "type": "string"
                        },
                        "id": {
                            "_format": "uri",
                            "description": "Link to a JSON that details the issuer's issuing and recovation keys. Default is https://[domain]/issuer/[org_abbr]-issuer.json. Included for (near) backward compatibility with open badges specification 1.1",
                            "type": "string"
                        },
                        "image": {
                            "description": "A base-64 encoded png image of the issuer's logo.",
                            "pattern": "data:image/png;base64,",
                            "type": "string"
                        },
                        "name": {
                            "description": "Name of the issuer.",
                            "type": "string"
                        },
                        "url": {
                            "_format": "uri",
                            "description": "URI of the issuer's homepage",
                            "type": "string"
                        }
                    },
                    "required": [
                        "image",
                        "id",
                        "url",
                        "name",
                        "email"
                    ],
                    "type": "object"
                },
                "language": {
                    "description": "Represents the ieft language and ieft country codes. Format is [ieft_language]-[IEFT_COUNTRY]. Backcompatible change to make this field not required.",
                    "pattern": "[a-z]{2}-[A-Z]{2}",
                    "type": "string"
                },
                "subtitle": {
                    "additionalProperties": false,
                    "description": "Subtitle of the certificate.",
                    "properties": {
                        "content": {
                            "description": "Content of the subtitle.",
                            "type": "string"
                        },
                        "display": {
                            "description": "Flag that indicates whether to show or hide the subtitle in the viewer. Backcompatible change to allow 2 types that occurred in the wild before proper validation.",
                            "oneOf": [
                                {
                                    "type": "string"
                                },
                                {
                                    "type": "boolean"
                                }
                            ]
                        }
                    },
                    "required": [
                        "content",
                        "display"
                    ],
                    "type": "object"
                },
                "title": {
                    "description": "Title of the certificate.",
                    "type": "string"
                }
            },
            "required": [
                "id",
                "image",
                "subtitle",
                "title",
                "issuer",
                "description"
            ],
            "type": "object"
        },
        "extension": {
            "description": "Extension object that includes extra fields not in the standard.",
            "properties": {
                "assertion": {
                    "properties": {},
                    "type": "object"
                },
                "certificate": {
                    "properties": {},
                    "type": "object"
                },
                "recipient": {
                    "properties": {},
                    "type": "object"
                },
                "verify": {
                    "properties": {},
                    "type": "object"
                }
            },
            "type": "object"
        },
        "recipient": {
            "additionalProperties": false,
            "properties": {
                "familyName": {
                    "description": "Family name of the recipient.",
                    "type": "string"
                },
                "givenName": {
                    "description": "Given name of the recipient",
                    "type": "string"
                },
                "hashed": {
                    "description": "Describes if the value in the identity field is hashed or not. Default is false, indicating that the identity is not hashed. Backcompatible change to allow 2 types that occurred in the wild before proper validation.",
                    "oneOf": [
                        {
                            "type": "string"
                        },
                        {
                            "type": "boolean"
                        }
                    ]
                },
                "identity": {
                    "description": "String that represents a recipient's identity. By default, it is an email address.",
                    "type": "string"
                },
                "pubkey": {
                    "description": "Bitcoin address (compressed public key, usually 24 characters) of the recipient.",
                    "type": "string"
                },
                "type": {
                    "description": "Type of value in the identity field. Default is 'email'.",
                    "type": "string"
                }
            },
            "required": [
                "familyName",
                "identity",
                "type",
                "hashed",
                "pubkey",
                "givenName"
            ],
            "type": "object"
        },
        "signature": {
            "description": "String of signature created when the Bitcoin private key signs the value in the attribute-signed field.",
            "type": "string"
        },
        "verify": {
            "additionalProperties": false,
            "properties": {
                "attribute-signed": {
                    "description": "Name of the attribute in the json that is signed by the issuer's private key. Default is 'uid', referring to the uid attribute.",
                    "type": "string"
                },
                "signer": {
                    "_format": "uri",
                    "description": "URI where issuer's public key is presented. Default is https://[domain]/keys/[org-abbr]-certs-public-key.asc. Compatible with open badges specification v1.1. Ideally, we would change this to point to a JSON instead, so we could retire keys (similar to the way we handle the issuer ID), but for now we're sticking with the OBS 1.1.",
                    "type": "string"
                },
                "type": {
                    "description": "Name of the signing method. Default is 'ECDSA(secp256k1)', referring to the Bitcoin method of signing messages with the issuer's private key.",
                    "type": "string"
                }
            },
            "required": [
                "attribute-signed",
                "type",
                "signer"
            ],
            "type": "object"
        }
    },
    "required": [
        "certificate",
        "assertion",
        "verify",
        "recipient"
    ],
    "title": "Certificate schema V1.1",
    "type": "object"
}

