        },
        "viewEncapsulation": {
            "alias": "v",
            "description": "The view encapsulation strategy to use in the new component.",
            "enum": [
                "Emulated",
                "Native",
                "None",
                "ShadowDom"
            ],
            "type": "string",
            "x-user-analytics": 11
        }
    },
    "required": [
        "name"
    ],
    "title": "Angular Component Options Schema",
    "type": "object"
