                }
            }
        },
        "resourceKind": {
            "type": "string",
            "maxLength": 64,
            "pattern": "(^[a-zA-Z0-9_.()-]+$)",
            "description": "Kind of resource"
        },
        "resourcePlan": {
            "type": "object",
            "properties": {
                "name": {
                    "type": "string",
                    "description": "Name of the plan"
                },
                "promotionCode": {
                    "type": "string",
                    "description": "Plan promotion code"
                },
                "publisher": {
                    "type": "string",
                    "description": "Name of the publisher"
                },
                "product": {
                    "type": "string",
                    "description": "Name of the product"
                },
                "version": {
                    "type": "string",
                    "description": "Version of the product"
                }
            },
            "required": [
                "name"
            ],
            "description": "Plan of the resource"
        },
        "resourceLocations": {
            "anyOf": [
                {
                    "type": "string"
                },
                {
                    "enum": [
                        "East Asia",
                        "Southeast Asia",
                        "Central US",
                        "East US",
                        "East US 2",
                        "West US",
                        "North Central US",
                        "South Central US",
                        "North Europe",
                        "West Europe",
                        "Japan West",
                        "Japan East",
                        "Brazil South",
                        "Australia East",
                        "Australia Southeast",
                        "Central India",
                        "West India",
                        "South India",
                        "Canada Central",
                        "Canada East",
                        "West Central US",
                        "West US 2",
                        "UK South",
                        "UK West",
                        "Korea Central",
                        "Korea South",
                        "global"
                    ]
                }
            ]
        },
        "expression": {
            "type": "string",
            "pattern": "^\\[([^\\[].*)?\\]$",
            "description": "Deployment template expression. See https://aka.ms/arm-template-expressions for more details on the ARM expression syntax."
        },
        "numberOrExpression": {
            "oneOf": [
                {
                    "type": "number"
                },
                {
                    "$ref": "#/definitions/expression"
                }
            ]
        },
        "Iso8601Duration": {
            "type": "string",
            "pattern": "^P(\\d+Y)?(\\d+M)?(\\d+D)?(T(((\\d+H)(\\d+M)?(\\d+(\\.\\d{1,2})?S)?)|((\\d+M)(\\d+(\\.\\d{1,2})?S)?)|((\\d+(\\.\\d{1,2})?S))))?$"
        },
        "UTC": {
            "type": "string",
            "pattern": "^\\d{4}(-(0[1-9]|1[0-2])(-([012]\\d|3[01])(T((([01]\\d|2[0123]):[0-5]\\d)|(24:00))(:(([0-5]\\d)|60)(\\.\\d{1,}){0,1}){0,1}){0,1}((Z)|([+-]((([01]\\d|2[0123]):[0-5]\\d)|(24:00)))){0,1}){0,1}){0,1}$"
        },
        "apiVersion": {
            "type": "string",
            "pattern": "(^((\\d\\d\\d\\d-\\d\\d-\\d\\d)|([0-9]+(\\.[0-9]+)?))(-[a-zA-Z][a-zA-Z0-9]*)?$)",
            "description": "API version of the resource type"
        }
    },
    "properties": {
        "ARMResourceBase": {
            "$ref": "#/definitions/ARMResourceBase"
        },
        "proxyResourceBase": {
            "$ref": "#/definitions/proxyResourceBase"
        },
        "resourceBase": {
            "$ref": "#/definitions/resourceBase"
        },
        "resourceBaseExternal": {
            "$ref": "#/definitions/resourceBaseExternal"
        },
        "resourceSku": {
            "$ref": "#/definitions/resourceSku"
        },
        "resourceCopy": {
            "$ref": "#/definitions/resourceCopy"
        },
        "resourceKind": {
            "$ref": "#/definitions/resourceKind"
        },
        "resourcePlan": {
            "$ref": "#/definitions/resourcePlan"
        },
        "resourceLocations": {
            "$ref": "#/definitions/resourceLocations"
        },
        "expression": {
            "$ref": "#/definitions/expression"
        },
        "numberOrExpression": {
            "$ref": "#/definitions/numberOrExpression"
        },
        "Iso8601Duration": {
            "$ref": "#/definitions/Iso8601Duration"
        },
        "UTC": {
            "$ref": "#/definitions/UTC"
        },
        "apiVersion": {
            "$ref": "#/definitions/apiVersion"
        }
    },
    "required": [
        "ARMResourceBase",
        "proxyResourceBase",
        "resourceBase",
        "resourceBaseExternal",
        "resourceSku",
        "resourceCopy",
        "resourceKind",
        "resourcePlan",
        "resourceLocations",
        "expression",
        "numberOrExpression",
        "Iso8601Duration",
        "UTC",
        "apiVersion"
    ]
}

