                                    "default": 60
                                },
                                "routing_engine_cpu_idle_check": {
                                    "type": "boolean",
                                    "description": "Enable/disable routing engine CLU idle time check",
                                    "default": true
                                }
                            }
                        },
                        "fpc": {
                            "type": "object",
                            "additionalProperties": false,
                            "default": {},
                            "properties": {
                                "fpc_cpu_5min_avg": {
                                    "type": "integer",
