                        "title": "BorderModuleGroups Terrains schema",
                        "type": "array"
                    }
                },
                "required": [
                    "Terrains",
                    "Filename"
                ],
                "title": "BorderModuleGroup item schema",
                "type": "object"
            },
            "minItems": 1,
            "title": "TopBorderModuleGroup schema",
            "type": "array",
            "_uniqueItems": true
        }
    },
    "required": [
