                "system_info": {
                    "type": "object",
                    "properties": {
                        "cpu_arch": {
                            "type": [
                                "string",
                                "null"
                            ],
                            "description": "Architecture of the CPU."
                        },
                        "cpu_count": {
                            "type": [
                                "integer",
                                "null"
                            ],
                            "description": "Number of CPU cores."
