                            "type": "string",
                            "description": "Reply sequence towards the meter. Should indicate the baud rate wanted. Will be send with initial baudrate. E.g. 063030300d0a for 300 baud. Use 'auto' to let vzlogger determine.",
                            "default": "auto"
                        },
                        "baudrate": {
                            "type": "integer",
